CREATE VIEW vw_preference_seed_calibration AS WITH seed_games AS (SELECT psg.PreferenceSeedID, psg.PreferenceTier, psg.ConditionalFlag, dg.GameKey, dg.GameID, dg.GameTitle FROM PreferenceSeedGame AS psg INNER JOIN DimGame AS dg ON ((dg.GameID = psg.GameID))), loo_similarity AS (SELECT "target".PreferenceSeedID, round(avg(CASE  WHEN (((sim.PreferenceTier IN ('S', 'A')) AND (sim.ConditionalFlag = CAST('f' AS BOOLEAN)) AND (sim.SeedGameID != "target".GameID))) THEN (sim.similarity_pct) ELSE NULL END), 2) AS loo_favorite_similarity, round(avg(CASE  WHEN (((sim.PreferenceTier IN ('B', 'C')) AND (sim.SeedGameID != "target".GameID))) THEN (sim.similarity_pct) ELSE NULL END), 2) AS loo_lower_similarity FROM seed_games AS "target" INNER JOIN vw_game_seed_similarity AS sim ON ((sim.GameID = "target".GameID)) GROUP BY "target".PreferenceSeedID)SELECT sg.PreferenceSeedID, sg.PreferenceTier, sg.ConditionalFlag, sg.GameID, sg.GameTitle, r.explicit_preference_score, ls.loo_favorite_similarity, ls.loo_lower_similarity, round((ls.loo_favorite_similarity - ls.loo_lower_similarity), 2) AS loo_preference_margin, r.playability_adjustment, r.adjusted_preference_score FROM seed_games AS sg LEFT JOIN mart_recommendation_v4 AS r ON ((r.GameKey = sg.GameKey)) LEFT JOIN loo_similarity AS ls ON ((ls.PreferenceSeedID = sg.PreferenceSeedID));
